import React, { useState } from 'react';
import { Container, Row, Col, Card, Form, Button, Alert, ProgressBar } from 'react-bootstrap';
import axios from 'axios';

const ImportPortfolio = () => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [message, setMessage] = useState({ text: '', type: '' });
  const [mappedFields, setMappedFields] = useState({
    date: 'Date',
    symbol: 'Ticker',
    quantity: 'Quantity',
    price: 'Price',
    type: 'Type'
  });

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
    setMessage({ text: '', type: '' });
  };

  const handleFieldMapping = (field, value) => {
    setMappedFields({
      ...mappedFields,
      [field]: value
    });
  };

  const handleUpload = async (e) => {
    e.preventDefault();

    if (!file) {
      setMessage({ text: 'Please select a file to upload', type: 'danger' });
      return;
    }

    const formData = new FormData();
    formData.append('file', file);
    // Add field mappings
    Object.keys(mappedFields).forEach(key => {
      formData.append(`field_${key}`, mappedFields[key]);
    });

    setUploading(true);
    setProgress(0);

    try {
      // This would normally point to your backend API
      // Since we don't have a real endpoint yet, we'll simulate success
      // await axios.post('/api/portfolio/import', formData, {
      //   onUploadProgress: (progressEvent) => {
      //     const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
      //     setProgress(percentCompleted);
      //   }
      // });

      // Simulate upload progress
      for (let i = 0; i <= 100; i += 10) {
        await new Promise(resolve => setTimeout(resolve, 200));
        setProgress(i);
      }

      setMessage({ 
        text: 'Portfolio data imported successfully! You can now view your portfolio performance.',
        type: 'success' 
      });

    } catch (error) {
      console.error(error);
      setMessage({ 
        text: 'Failed to import portfolio data. Please check your file format and try again.',
        type: 'danger' 
      });
    } finally {
      setUploading(false);
    }
  };

  return (
    <Container className="mt-4">
      <h1 className="mb-4">Import Portfolio Data</h1>

      {message.text && (
        <Alert variant={message.type}>
          {message.text}
          {message.type === 'success' && (
            <div className="mt-2">
              <Button variant="primary" href="/portfolios">View Portfolio</Button>
            </div>
          )}
        </Alert>
      )}

      <Row>
        <Col lg={6} className="mb-4">
          <Card>
            <Card.Body>
              <Card.Title>Upload Portfolio File</Card.Title>
              <Card.Text>
                Import your portfolio data from a CSV or Excel file.
              </Card.Text>

              <Form onSubmit={handleUpload}>
                <Form.Group className="mb-3">
                  <Form.Label>Choose File</Form.Label>
                  <div className="file-upload-container p-3 mb-3">
                    <Form.Control 
                      type="file" 
                      accept=".csv,.xlsx,.xls" 
                      onChange={handleFileChange}
                      disabled={uploading}
                    />
                  </div>

                  {file && (
                    <div className="mt-2 mb-3">
                      <p><strong>Selected file:</strong> {file.name}</p>
                    </div>
                  )}

                  {uploading && (
                    <ProgressBar 
                      now={progress} 
                      label={`${progress}%`} 
                      className="mb-3"
                      animated
                    />
                  )}
                </Form.Group>

                <Button 
                  variant="primary" 
                  type="submit" 
                  disabled={!file || uploading}
                >
                  {uploading ? 'Uploading...' : 'Upload Portfolio'}
                </Button>
              </Form>
            </Card.Body>
          </Card>
        </Col>

        <Col lg={6}>
          <Card>
            <Card.Body>
              <Card.Title>Column Mapping</Card.Title>
              <Card.Text>
                Map the columns in your file to the required fields.
              </Card.Text>

              <Form.Group className="mb-3">
                <Form.Label>Date Column</Form.Label>
                <Form.Control 
                  type="text" 
                  placeholder="Enter date column name"
                  value={mappedFields.date}
                  onChange={(e) => handleFieldMapping('date', e.target.value)}
                  disabled={uploading}
                />
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>Symbol/Ticker Column</Form.Label>
                <Form.Control 
                  type="text" 
                  placeholder="Enter symbol column name"
                  value={mappedFields.symbol}
                  onChange={(e) => handleFieldMapping('symbol', e.target.value)}
                  disabled={uploading}
                />
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>Quantity Column</Form.Label>
                <Form.Control 
                  type="text" 
                  placeholder="Enter quantity column name"
                  value={mappedFields.quantity}
                  onChange={(e) => handleFieldMapping('quantity', e.target.value)}
                  disabled={uploading}
                />
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>Price Column</Form.Label>
                <Form.Control 
                  type="text" 
                  placeholder="Enter price column name"
                  value={mappedFields.price}
                  onChange={(e) => handleFieldMapping('price', e.target.value)}
                  disabled={uploading}
                />
              </Form.Group>

              <Form.Group className="mb-3">
                <Form.Label>Transaction Type Column</Form.Label>
                <Form.Control 
                  type="text" 
                  placeholder="Enter transaction type column name"
                  value={mappedFields.type}
                  onChange={(e) => handleFieldMapping('type', e.target.value)}
                  disabled={uploading}
                />
              </Form.Group>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      <Row className="mt-4">
        <Col>
          <Card>
            <Card.Body>
              <Card.Title>File Format Guidelines</Card.Title>
              <Card.Text>
                Your portfolio file should contain the following information:
              </Card.Text>

              <ul>
                <li><strong>Date:</strong> The date of the transaction (YYYY-MM-DD format preferred)</li>
                <li><strong>Ticker/Symbol:</strong> The stock symbol or identifier</li>
                <li><strong>Quantity:</strong> Number of shares or units</li>
                <li><strong>Price:</strong> Price per share at the time of transaction</li>
                <li><strong>Type:</strong> Transaction type (e.g., BUY, SELL, DIVIDEND)</li>
              </ul>

              <Card.Text>
                Optional columns that can enhance analysis:
              </Card.Text>

              <ul>
                <li><strong>Fees:</strong> Any transaction fees or commissions</li>
                <li><strong>Sector:</strong> Business sector or industry classification</li>
                <li><strong>Asset Class:</strong> Type of asset (e.g., Stock, Bond, ETF)</li>
              </ul>

              <Card.Text className="mt-3 mb-0">
                <strong>Example CSV format:</strong>
              </Card.Text>
              <pre className="bg-light p-2 mt-2">
                Date,Ticker,Quantity,Price,Type,Fees,Sector<br/>
                2022-01-15,AAPL,10,172.50,BUY,5.99,Technology<br/>
                2022-03-20,MSFT,5,300.25,BUY,5.99,Technology<br/>
                2022-05-10,AAPL,2,155.30,SELL,5.99,Technology
              </pre>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default ImportPortfolio;
